import { test, expect } from '@playwright/test';

test.describe('Alert Dialog Blocking Page Interaction', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/alert-dialog');
  });

  test('should block interaction with page behind alert dialog', async ({ page }) => {
    // Open the alert dialog
    const openButton = page.getByRole('button', { name: /open alert/i });
    await openButton.click();

    // Verify alert dialog is visible
    const alertDialog = page.getByRole('dialog', { name: /alert/i });
    await expect(alertDialog).toBeVisible();

    // Verify overlay is visible
    const overlay = page.locator('[data-testid="overlay"]');
    await expect(overlay).toBeVisible();

    // Verify alert dialog content is visible
    const alertMessage = page.getByText(/this is an alert/i);
    await expect(alertMessage).toBeVisible();

    // Attempt to interact with page behind alert dialog
    const closeButton = page.getByRole('button', { name: /close/i });
    const pageContent = page.getByText(/page content/i);

    // Verify close button is not clickable when alert is open
    await expect(closeButton).not.toBeEnabled();

    // Verify page content is not visible or interactive
    await expect(pageContent).not.toBeVisible();

    // Close the alert dialog
    await closeButton.click();

    // Verify alert dialog is no longer visible
    await expect(alertDialog).not.toBeVisible();
  });

  test('should allow interaction with page behind alert dialog after closing it', async ({ page }) => {
    // Open the alert dialog
    const openButton = page.getByRole('button', { name: /open alert/i });
    await openButton.click();

    // Verify alert dialog is visible
    const alertDialog = page.getByRole('dialog', { name: /alert/i });
    await expect(alertDialog).toBeVisible();

    // Attempt to interact with page behind alert dialog (should fail)
    const pageContent = page.getByText(/page content/i);
    await expect(pageContent).not.toBeVisible();

    // Close the alert dialog
    const closeButton = page.getByRole('button', { name: /close/i });
    await closeButton.click();

    // Verify alert dialog is closed
    await expect(alertDialog).not.toBeVisible();

    // Verify page content is now visible and interactive
    await expect(pageContent).toBeVisible();

    // Verify page content can be interacted with
    const pageButton = page.getByRole('button', { name: /page button/i });
    await expect(pageButton).toBeEnabled();
    await pageButton.click();
  });
});
